script.inlineScript:
import { readFileSync, writeFileSync } from 'fs';
const input = JSON.parse(readFileSync('/output/input.json', 'utf8'));
const { source, batchSize, dryRun, domains } = input;
writeFileSync('/output/result.json', JSON.stringify({ processed: dryRun !== true, source, batchSize, domains, summary: `Processed ${source} (${domains.join(', ')}) in batches of ${batchSize}` }));
